#!/bin/sh
# demo/extract: run the extractor (extract.lisp) in ACL2's raw Lisp.
# Usage: sh extract/run.sh GEN_DIR SPEC_DIR OUT_DIR   (from demo/, inside
# `nix develop`; GEN_DIR = ../translate/gen/wasm-3.0, regenerated by
# `make -C translate check-3.0` or `gen SPEC=3.0`). Reads, never writes,
# GEN_DIR, rt/ and SPEC_DIR/t7-lib-3.0.lisp.
set -e
here=$(cd "$(dirname "$0")" && pwd)
gen=$(cd "$1" && pwd); spec=$(cd "$2" && pwd)
mkdir -p "$3"; out=$(cd "$3" && pwd)/
log=$out/extract.log
# The pure helpers of the ACL2 conformance driver (W2 item 4), by name: an
# unknown name is an error.
names='"vt-bits" "lane-bits" "lanes-nat" "nat-lanes" "to-val" "to-vals"
 "float-bits-ok" "lanes-ok" "ref-kind" "ref-ok" "val-ok" "either-ok" "vals-ok"
 "env-store" "env-inst" "chars-of" "str-bytes" "find-export" "registered"
 "resolve-imports" "*spec-fuel*" "run-steps" "final-config" "exn-result-p"
 "instantiate" "do-action" "value-instr-p" "all-values-p" "fail-class" "*s0*"
 "*data*" "parse-file" "run-cmd" "spectest-env"'
# W3 item 2: the checking functions of the ACL2 numeric test books, by name,
# and their data. The runners call CHECK-VECTORS and CHECK-SIMD as the books do.
tests=$(cd "$spec/.." && pwd)
numerics='"*ops*" "vt-of" "float-vt-p" "vt-bits" "to-val" "from-val" "search-char"
 "from-list" "run-cvt" "run-vector" "check-vectors"'
simd='"*simd-ops*" "relaxed-name-p" "arity-of" "vc" "vcs" "result-shape" "lanes-match"
 "v128-match" "run-instr" "map3" "full-profile-op" "run-full" "check-simd" "count-relaxed"'
mkdir -p "$out/data"
cd "$gen"
$ACL2 > "$log" 2>&1 <<LISP
(ld "portcullis.acl2")
:q
(load "$here/extract.lisp")
(setq demo-extract::*stack-rewrite* ${DEMO_STACK_REWRITE:-t})
(handler-case
    (progn (demo-extract::extract :root "$gen/wasm3.lisp" :driver "$spec/t7-lib-3.0.lisp"
                                  :driver-names '($names) :outdir "$out"
                                  :tests '(("numerics.lisp" "$tests/sem-3.0/t3-numerics-3.0.lisp" ($numerics))
                                           ("simd.lisp" "$tests/sem-3.0/t3-simd-3.0.lisp" ($simd)))
                                  :data '(("$tests/sem/numeric-vectors.lsp" "data/numeric-vectors.json")
                                          ("$tests/sem-2.0/numeric-vectors-2.0.lsp" "data/numeric-vectors-2.0.json")
                                          ("$tests/sem-3.0/simd-vectors-3.0.lsp" "data/simd-vectors-3.0.json"))
                                  :units "$here/../test/units.lsp")
           (format t "~&DEMO-EXTRACT-OK~%"))
  (error (c) (format t "~&DEMO-EXTRACT-ERROR ~A~%" c)))
LISP
cat "$out/REPORT" 2>/dev/null || true
if grep -q '^DEMO-EXTRACT-OK' "$log"; then exit 0; fi
grep -A3 'DEMO-EXTRACT-ERROR\|debugger invoked' "$log" | head -20
exit 1
